+            listenableFuture.addListener(future2, executorService, null);
+
+            final var success = randomBoolean();
+            if (success) {
+                listenableFuture.onResponse(null);
+            } else {
+                listenableFuture.onFailure(new ElasticsearchException("simulated"));
+            }
+
